export const isClipboardSupported = (): boolean => {
  if (typeof window === 'undefined' || typeof document === 'undefined') return false;
  // Modern API
  if (typeof navigator !== 'undefined' && (navigator as any).clipboard?.writeText) return true;
  // Fallback probe
